"""A dependency-free client for OpenAI's Responses API.

Prompts are sent only in the HTTPS request body.  This module does not log or
write prompts, API keys, or API responses to disk.  Set ``OPENAI_API_KEY`` in
the process environment before calling :func:`respond`.

Example::

    from openai_client import respond

    print(respond("Summarize this note: ...", model="gpt-5"))
"""

from __future__ import annotations

import json
import os
from typing import Any, Mapping
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


RESPONSES_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """An error returned while contacting the OpenAI API.

    Error response bodies are deliberately not retained: they can sometimes
    include request-derived content, which callers may consider sensitive.
    """

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


def create_response(
    prompt: str,
    *,
    model: str,
    api_key: str | None = None,
    timeout: float = 60.0,
    api_url: str = RESPONSES_URL,
    **options: Any,
) -> dict[str, Any]:
    """Send one text prompt and return the decoded Responses API object.

    ``options`` is passed through to the API (for example, ``instructions``,
    ``max_output_tokens``, or ``store=False``).  Values supplied in ``options``
    may not replace ``model`` or ``input``.

    ``api_key`` is accepted for applications that manage secrets themselves;
    otherwise the ``OPENAI_API_KEY`` environment variable is used.  The key is
    never logged or included in raised error messages.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be positive")
    if "model" in options or "input" in options:
        raise ValueError("pass model and prompt through their named parameters")

    key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("No API key: set OPENAI_API_KEY or pass api_key.")

    payload = {"model": model, "input": prompt, **options}
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = Request(
        api_url,
        data=body,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.load(response)
    except HTTPError as exc:
        raise OpenAIError(f"OpenAI API returned HTTP {exc.code}.", status=exc.code) from None
    except URLError as exc:
        raise OpenAIError("Could not reach the OpenAI API.") from exc
    except (OSError, json.JSONDecodeError) as exc:
        raise OpenAIError("OpenAI API returned an unreadable response.") from exc

    if not isinstance(result, dict):
        raise OpenAIError("OpenAI API returned an unexpected response format.")
    return result


def output_text(response: Mapping[str, Any]) -> str:
    """Return concatenated text from a Responses API response object."""
    direct_text = response.get("output_text")
    if isinstance(direct_text, str):
        return direct_text

    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if isinstance(content, Mapping) and content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    parts.append(text)
    return "".join(parts)


def respond(prompt: str, *, model: str, **options: Any) -> str:
    """Send a prompt and return only its generated text."""
    return output_text(create_response(prompt, model=model, **options))
